(() => {
'use strict';
const api=window.RaceRuntime,game=window.Ardenne,$=id=>document.getElementById(id),startRace=game.startRace,openTimeAttack=game.openTimeAttack,mainMenu=game.mainMenu,originalRestart=$('restart').onclick,diagnostics=window.racingDiagnostics;
game.startRace=options=>{const config={...RaceGrid.config(options),...options};api.prepare(config);startRace(config);};
game.openTimeAttack=()=>{api.deactivate();openTimeAttack();};game.mainMenu=()=>{api.deactivate();mainMenu();$('menu-home').hidden=false;$('race-setup').hidden=true;$('settings-panel').hidden=true;};api.restart=()=>game.startRace(api.config);
$('restart').onclick=()=>{if(api.active)api.restart();else originalRestart();};$('race-again').onclick=()=>api.restart();$('results-menu').onclick=()=>game.mainMenu();
function time(seconds){return String(Math.floor(seconds/60)).padStart(2,'0')+':'+(seconds%60).toFixed(3).padStart(6,'0');}
const lamps=Array.from({length:5},(_,i)=>$('start-lamp-'+i));let lastResult=null;
api.onHide=()=>{$('race-start-lights').hidden=true;$('race-results').hidden=true;lastResult=null;};
api.onFrame=()=>{if(!api.active)return;const state=api.controller.state,order=api.controller.standings(),position=order.findIndex(d=>d.id==='player')+1,player=state.player;
 $('race-start-lights').hidden=!state.lightsVisible;$('race-start-lights').setAttribute('aria-label',state.redLights+' of 5 start lights red');lamps.forEach((lamp,i)=>{lamp.classList.toggle('red',i<state.redLights);});
 $('race-info').textContent='P'+String(position).padStart(2,'0')+' / 20 · AI '+api.config.aiDifficulty;$('lap').textContent=Math.min(api.config.laps,player.completedLaps+1)+' / '+api.config.laps;$('timer').textContent=time(state.raceTime);$('status').textContent=state.phase==='finished'?'FINISHED':state.phase==='racing'?'RACING':'GRID';
 if(state.phase==='wait')$('notice').textContent='GRID LOCKED · THROTTLE READY';else if(state.lightsVisible)$('notice').textContent='WAIT FOR LIGHTS OUT';else if(state.phase==='racing'&&state.raceTime<2)$('notice').textContent='LIGHTS OUT · RACE ON';else if(['GRID LOCKED · THROTTLE READY','WAIT FOR LIGHTS OUT','LIGHTS OUT · RACE ON'].includes($('notice').textContent))$('notice').textContent='';
 const finished=state.phase==='finished'||api.config.multiplayer&&player.finished;$('race-results').hidden=!finished;if(finished&&lastResult!==state){lastResult=state;$('race-result-position').textContent='P'+position;$('race-result-summary').textContent=api.config.laps+' LAPS · '+time(state.raceTime)+' · AI '+api.config.aiDifficulty;const list=$('race-result-list');list.replaceChildren();order.forEach((d,i)=>{const row=document.createElement('div');row.className='result-row'+(d.id==='player'?' you':'');const pos=document.createElement('span'),name=document.createElement('strong'),result=document.createElement('span');pos.textContent=String(i+1).padStart(2,'0');name.textContent=d.name;result.textContent=d.finishTime!==null?time(d.finishTime):'LAP '+Math.min(api.config.laps,d.completedLaps+1);row.appendChild(pos);row.appendChild(name);row.appendChild(result);list.appendChild(row);});}
};
window.racingDiagnostics=()=>{const base=diagnostics();if(api.active){const s=api.controller.state;base.race={phase:s.phase,redLights:s.redLights,lightsVisible:s.lightsVisible,goTime:s.goTime,elapsed:s.elapsed,raceTime:s.raceTime,laps:api.config.laps,position:api.controller.standings().findIndex(d=>d.id==='player')+1,completedLaps:s.player.completedLaps,finished:s.player.finished,opponents:s.drivers.length,passes:s.passes,brakingLead:api.controller.brakingLead};}return base;};
})();
